using System.ComponentModel.DataAnnotations;

namespace ShipmentTracker.Data;

public class Shipment
{
    public int Id { get; set; }

    [Required]
    [MaxLength(50)]
    public string TrackingNumber { get; set; } = string.Empty;

    [Required]
    [MaxLength(200)]
    public string Origin { get; set; } = string.Empty;

    [Required]
    [MaxLength(200)]
    public string Destination { get; set; } = string.Empty;

    public ShipmentStatus Status { get; set; } = ShipmentStatus.Pending;

    public DateTime CreatedAt { get; set; } = DateTime.UtcNow;

    public DateTime? EstimatedDelivery { get; set; }

    [MaxLength(500)]
    public string? Notes { get; set; }

    // The customer (ApplicationUser) who owns this shipment
    [Required]
    public string CustomerId { get; set; } = string.Empty;
    public ApplicationUser Customer { get; set; } = null!;

    // The dispatcher who last updated it
    public string? DispatcherId { get; set; }
    public ApplicationUser? Dispatcher { get; set; }
}

public enum ShipmentStatus
{
    Pending,
    PickedUp,
    InTransit,
    OutForDelivery,
    Delivered,
    Cancelled
}

using Microsoft.AspNetCore.Identity;

namespace ShipmentTracker.Data;

public class ApplicationUser : IdentityUser
{
    public string Role { get; set; } = "Customer"; // "Customer" or "Dispatcher"
}

