using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Client.Services;
using ShipmentTracker.Data;

namespace ShipmentTracker.Services;

public class ShipmentServerService(ApplicationDbContext db, UserManager<ApplicationUser> userManager) : IShipmentService
{
    public async Task<List<ShipmentDto>> GetAllShipmentsAsync()
    {
        return await db.Shipments
            .Include(s => s.Customer)
            .OrderByDescending(s => s.CreatedAt)
            .Select(s => ToDto(s))
            .ToListAsync();
    }

    public Task<List<ShipmentDto>> GetMyShipmentsAsync()
    {
        // Server-side prerender won't have user context; return empty
        return Task.FromResult(new List<ShipmentDto>());
    }

    public async Task<ShipmentDto?> GetShipmentByTrackingNumberAsync(string trackingNumber)
    {
        var shipment = await db.Shipments
            .Include(s => s.Customer)
            .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);
        return shipment is null ? null : ToDto(shipment);
    }

    public async Task<ShipmentDto> CreateShipmentAsync(CreateShipmentRequest request)
    {
        var customer = await userManager.FindByEmailAsync(request.CustomerEmail)
            ?? throw new InvalidOperationException("Customer not found");

        var shipment = new Shipment
        {
            TrackingNumber = GenerateTrackingNumber(),
            Origin = request.Origin,
            Destination = request.Destination,
            CustomerId = customer.Id,
            EstimatedDelivery = request.EstimatedDelivery,
            Notes = request.Notes,
            Status = ShipmentStatus.Pending
        };

        db.Shipments.Add(shipment);
        await db.SaveChangesAsync();

        shipment.Customer = customer;
        return ToDto(shipment);
    }

    public async Task UpdateStatusAsync(UpdateShipmentStatusRequest request)
    {
        var shipment = await db.Shipments.FindAsync(request.ShipmentId)
            ?? throw new InvalidOperationException("Shipment not found");

        shipment.Status = Enum.Parse<ShipmentStatus>(request.Status);
        if (request.Notes is not null)
            shipment.Notes = request.Notes;

        await db.SaveChangesAsync();
    }

    private static ShipmentDto ToDto(Shipment s) => new()
    {
        Id = s.Id,
        TrackingNumber = s.TrackingNumber,
        Origin = s.Origin,
        Destination = s.Destination,
        Status = s.Status.ToString(),
        CreatedAt = s.CreatedAt,
        EstimatedDelivery = s.EstimatedDelivery,
        Notes = s.Notes,
        CustomerEmail = s.Customer?.Email ?? ""
    };

    private static string GenerateTrackingNumber()
    {
        return $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpper()}";
    }
}

using System.Security.Claims;
using Microsoft.AspNetCore.Identity;
using Microsoft.AspNetCore.Mvc;
using Microsoft.EntityFrameworkCore;
using ShipmentTracker.Client.Models;
using ShipmentTracker.Data;

namespace ShipmentTracker.Endpoints;

public static class ShipmentEndpoints
{
    public static void MapShipmentEndpoints(this WebApplication app)
    {
        var group = app.MapGroup("api/shipments").RequireAuthorization();

        // Get all shipments (dispatchers)
        group.MapGet("/", async (ApplicationDbContext db) =>
        {
            var shipments = await db.Shipments
                .Include(s => s.Customer)
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status.ToString(),
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    Notes = s.Notes,
                    CustomerEmail = s.Customer.Email ?? ""
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Get current user's shipments (customers)
        group.MapGet("/mine", async (ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var userId = user.FindFirstValue(ClaimTypes.NameIdentifier);
            var shipments = await db.Shipments
                .Include(s => s.Customer)
                .Where(s => s.CustomerId == userId)
                .OrderByDescending(s => s.CreatedAt)
                .Select(s => new ShipmentDto
                {
                    Id = s.Id,
                    TrackingNumber = s.TrackingNumber,
                    Origin = s.Origin,
                    Destination = s.Destination,
                    Status = s.Status.ToString(),
                    CreatedAt = s.CreatedAt,
                    EstimatedDelivery = s.EstimatedDelivery,
                    Notes = s.Notes,
                    CustomerEmail = s.Customer.Email ?? ""
                })
                .ToListAsync();

            return Results.Ok(shipments);
        });

        // Track by tracking number (authenticated users)
        group.MapGet("/track/{trackingNumber}", async (string trackingNumber, ApplicationDbContext db) =>
        {
            var shipment = await db.Shipments
                .Include(s => s.Customer)
                .FirstOrDefaultAsync(s => s.TrackingNumber == trackingNumber);

            if (shipment is null) return Results.NotFound();

            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status.ToString(),
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery,
                Notes = shipment.Notes,
                CustomerEmail = shipment.Customer?.Email ?? ""
            });
        });

        // Create shipment (dispatchers)
        group.MapPost("/", async ([FromBody] CreateShipmentRequest request, ApplicationDbContext db, UserManager<ApplicationUser> userManager) =>
        {
            var customer = await userManager.FindByEmailAsync(request.CustomerEmail);
            if (customer is null) return Results.BadRequest("Customer not found");

            var shipment = new Shipment
            {
                TrackingNumber = $"SHP-{DateTime.UtcNow:yyyyMMdd}-{Guid.NewGuid().ToString()[..8].ToUpper()}",
                Origin = request.Origin,
                Destination = request.Destination,
                CustomerId = customer.Id,
                EstimatedDelivery = request.EstimatedDelivery,
                Notes = request.Notes,
                Status = ShipmentStatus.Pending
            };

            db.Shipments.Add(shipment);
            await db.SaveChangesAsync();

            shipment.Customer = customer;
            return Results.Ok(new ShipmentDto
            {
                Id = shipment.Id,
                TrackingNumber = shipment.TrackingNumber,
                Origin = shipment.Origin,
                Destination = shipment.Destination,
                Status = shipment.Status.ToString(),
                CreatedAt = shipment.CreatedAt,
                EstimatedDelivery = shipment.EstimatedDelivery,
                Notes = shipment.Notes,
                CustomerEmail = customer.Email ?? ""
            });
        });

        // Update shipment status (dispatchers)
        group.MapPut("/status", async ([FromBody] UpdateShipmentStatusRequest request, ApplicationDbContext db, ClaimsPrincipal user) =>
        {
            var shipment = await db.Shipments.FindAsync(request.ShipmentId);
            if (shipment is null) return Results.NotFound();

            shipment.Status = Enum.Parse<ShipmentStatus>(request.Status);
            shipment.DispatcherId = user.FindFirstValue(ClaimTypes.NameIdentifier);
            if (request.Notes is not null)
                shipment.Notes = request.Notes;

            await db.SaveChangesAsync();
            return Results.Ok();
        });
    }
}

