@page "/shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Dispatcher - All Shipments</PageTitle>

<h3>📦 Shipment Dashboard</h3>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or status..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.TrackingNumber))" style="cursor:pointer">Tracking # ⇅</th>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.Destination))" style="cursor:pointer">Destination ⇅</th>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.Status))" style="cursor:pointer">Status ⇅</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.CustomerEmail</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                    value="@s.Status" @onchange="e => UpdateStatus(s, e.Value?.ToString())">
                                <option value="Pending">Pending</option>
                                <option value="PickedUp">Picked Up</option>
                                <option value="InTransit">In Transit</option>
                                <option value="OutForDelivery">Out for Delivery</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Cancelled">Cancelled</option>
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-info mt-2">@statusMessage</div>
}

@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string sortColumn = nameof(ShipmentDto.CreatedAt);
    private bool sortAscending = false;
    private string? statusMessage;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(filterText)
                || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            .OrderBy(s => sortColumn switch
            {
                nameof(ShipmentDto.TrackingNumber) => s.TrackingNumber as object,
                nameof(ShipmentDto.Destination) => s.Destination,
                nameof(ShipmentDto.Status) => s.Status,
                _ => s.CreatedAt as object
            }, sortAscending ? Comparer<object>.Default : Comparer<object>.Create((a, b) => Comparer<object>.Default.Compare(b, a)));

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus) || newStatus == shipment.Status) return;

        await ShipmentService.UpdateStatusAsync(new UpdateShipmentStatusRequest
        {
            ShipmentId = shipment.Id,
            Status = newStatus
        });

        shipment.Status = newStatus;
        statusMessage = $"Updated {shipment.TrackingNumber} to {newStatus}";
        StateHasChanged();
        await Task.Delay(3000);
        statusMessage = null;
        StateHasChanged();
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/my-shipments"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>My Shipments</PageTitle>

<h3>📬 My Shipments</h3>

@if (shipments is null)
{
    <p><em>Loading your shipments...</em></p>
}
else if (!shipments.Any())
{
    <p>You don't have any shipments yet.</p>
}
else
{
    <div class="row">
        @foreach (var s in shipments)
        {
            <div class="col-md-6 col-lg-4 mb-3">
                <div class="card h-100">
                    <div class="card-header d-flex justify-content-between align-items-center">
                        <code>@s.TrackingNumber</code>
                        <span class="badge @GetStatusBadge(s.Status)">@s.Status</span>
                    </div>
                    <div class="card-body">
                        <p><strong>From:</strong> @s.Origin</p>
                        <p><strong>To:</strong> @s.Destination</p>
                        @if (s.EstimatedDelivery.HasValue)
                        {
                            <p><strong>Estimated Delivery:</strong> @s.EstimatedDelivery.Value.ToString("MMMM dd, yyyy")</p>
                        }
                        @if (!string.IsNullOrEmpty(s.Notes))
                        {
                            <p class="text-muted"><small>@s.Notes</small></p>
                        }
                    </div>
                    <div class="card-footer text-muted">
                        <small>Created: @s.CreatedAt.ToString("MMM dd, yyyy HH:mm") UTC</small>
                    </div>
                </div>
            </div>
        }
    </div>
}

@code {
    private List<ShipmentDto>? shipments;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetMyShipmentsAsync();
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h3>🔍 Track a Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260614-AB12CD34)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && result is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>.
    </div>
}
else if (result is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between">
            <span><strong>@result.TrackingNumber</strong></span>
            <span class="badge @GetStatusBadge(result.Status) fs-6">@result.Status</span>
        </div>
        <div class="card-body">
            <div class="mb-3">
                <h6>Route</h6>
                <p class="mb-0">@result.Origin → @result.Destination</p>
            </div>

            @if (result.EstimatedDelivery.HasValue)
            {
                <div class="mb-3">
                    <h6>Estimated Delivery</h6>
                    <p class="mb-0 fs-5 text-primary">@result.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</p>
                </div>
            }

            <div class="mb-3">
                <h6>Shipment Created</h6>
                <p class="mb-0">@result.CreatedAt.ToString("MMMM dd, yyyy HH:mm") UTC</p>
            </div>

            @if (!string.IsNullOrEmpty(result.Notes))
            {
                <div>
                    <h6>Notes</h6>
                    <p class="mb-0 text-muted">@result.Notes</p>
                </div>
            }
        </div>

        <!-- Progress visualization -->
        <div class="card-footer">
            <div class="d-flex justify-content-between small text-muted mb-1">
                <span>Pending</span><span>Picked Up</span><span>In Transit</span><span>Out for Delivery</span><span>Delivered</span>
            </div>
            <div class="progress" style="height: 8px;">
                <div class="progress-bar @GetProgressBarColor(result.Status)" style="width: @GetProgressPercent(result.Status)%"></div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? result;
    private bool searched;
    private bool isSearching;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isSearching = true;
        searchedNumber = trackingNumber.Trim();
        result = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
        isSearching = false;
    }

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        _ => 0
    };

    private static string GetProgressBarColor(string status) => status switch
    {
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

@page "/shipments/new"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
