@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Dispatcher - All Shipments</PageTitle>

<h3>📦 Shipment Dashboard</h3>

<div class="mb-3">
    <input type="text" class="form-control" placeholder="Filter by tracking #, destination, or status..."
           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.TrackingNumber))" style="cursor:pointer">Tracking # ⇅</th>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.Destination))" style="cursor:pointer">Destination ⇅</th>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.Status))" style="cursor:pointer">Status ⇅</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
            <tbody>
                @foreach (var s in FilteredShipments)
                {
                    <tr>
                        <td><code>@s.TrackingNumber</code></td>
                        <td>@s.Destination</td>
                        <td><span class="badge @GetStatusBadge(s.Status)">@s.Status</span></td>
                        <td>@s.CustomerEmail</td>
                        <td>@(s.EstimatedDelivery?.ToString("MMM dd, yyyy") ?? "—")</td>
                        <td>
                            <select class="form-select form-select-sm" style="width:auto;display:inline-block"
                                    value="@s.Status" @onchange="e => UpdateStatus(s, e.Value?.ToString())">
                                <option value="Pending">Pending</option>
                                <option value="PickedUp">Picked Up</option>
                                <option value="InTransit">In Transit</option>
                                <option value="OutForDelivery">Out for Delivery</option>
                                <option value="Delivered">Delivered</option>
                                <option value="Cancelled">Cancelled</option>
                            </select>
                        </td>
                    </tr>
                }
            </tbody>
        </table>
    </div>
}

@if (!string.IsNullOrEmpty(statusMessage))
{
    <div class="alert alert-info mt-2">@statusMessage</div>
