@code {
    private List<ShipmentDto>? shipments;
    private string filterText = "";
    private string sortColumn = nameof(ShipmentDto.CreatedAt);
    private bool sortAscending = false;
    private string? statusMessage;

    protected override async Task OnInitializedAsync()
    {
        shipments = await ShipmentService.GetAllShipmentsAsync();
    }

    private IEnumerable<ShipmentDto> FilteredShipments =>
        (shipments ?? [])
            .Where(s => string.IsNullOrEmpty(filterText)
                || s.TrackingNumber.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Destination.Contains(filterText, StringComparison.OrdinalIgnoreCase)
                || s.Status.Contains(filterText, StringComparison.OrdinalIgnoreCase))
            .OrderBy(s => sortColumn switch
            {
                nameof(ShipmentDto.TrackingNumber) => s.TrackingNumber as object,
                nameof(ShipmentDto.Destination) => s.Destination,
                nameof(ShipmentDto.Status) => s.Status,
                _ => s.CreatedAt as object
            }, sortAscending ? Comparer<object>.Default : Comparer<object>.Create((a, b) => Comparer<object>.Default.Compare(b, a)));

    private void SortBy(string column)
    {
        if (sortColumn == column)
            sortAscending = !sortAscending;
        else
        {
            sortColumn = column;
            sortAscending = true;
        }
    }

    private async Task UpdateStatus(ShipmentDto shipment, string? newStatus)
    {
        if (string.IsNullOrEmpty(newStatus) || newStatus == shipment.Status) return;

        await ShipmentService.UpdateStatusAsync(new UpdateShipmentStatusRequest
        {
            ShipmentId = shipment.Id,
            Status = newStatus
        });

        shipment.Status = newStatus;
        statusMessage = $"Updated {shipment.TrackingNumber} to {newStatus}";
        StateHasChanged();
        await Task.Delay(3000);
        statusMessage = null;
        StateHasChanged();
    }

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

