@page "/track"
@using Microsoft.AspNetCore.Authorization
@using ShipmentTracker.Client.Models
@using ShipmentTracker.Client.Services
@attribute [Authorize]
@inject IShipmentService ShipmentService
@rendermode InteractiveAuto

<PageTitle>Track Shipment</PageTitle>

<h3>🔍 Track a Shipment</h3>

<div class="row mb-4">
    <div class="col-md-6">
        <div class="input-group">
            <input type="text" class="form-control" placeholder="Enter tracking number (e.g., SHP-20260614-AB12CD34)"
                   @bind="trackingNumber" @onkeydown="HandleKeyDown" />
            <button class="btn btn-primary" @onclick="Search" disabled="@isSearching">
                @(isSearching ? "Searching..." : "Track")
            </button>
        </div>
    </div>
</div>

@if (searched && result is null)
{
    <div class="alert alert-warning">
        No shipment found with tracking number <strong>@searchedNumber</strong>.
    </div>
}
else if (result is not null)
{
    <div class="card" style="max-width: 600px;">
        <div class="card-header d-flex justify-content-between">
            <span><strong>@result.TrackingNumber</strong></span>
            <span class="badge @GetStatusBadge(result.Status) fs-6">@result.Status</span>
        </div>
        <div class="card-body">
            <div class="mb-3">
                <h6>Route</h6>
                <p class="mb-0">@result.Origin → @result.Destination</p>
            </div>

            @if (result.EstimatedDelivery.HasValue)
            {
                <div class="mb-3">
                    <h6>Estimated Delivery</h6>
                    <p class="mb-0 fs-5 text-primary">@result.EstimatedDelivery.Value.ToString("dddd, MMMM dd, yyyy")</p>
                </div>
            }

            <div class="mb-3">
                <h6>Shipment Created</h6>
                <p class="mb-0">@result.CreatedAt.ToString("MMMM dd, yyyy HH:mm") UTC</p>
            </div>

            @if (!string.IsNullOrEmpty(result.Notes))
            {
                <div>
                    <h6>Notes</h6>
                    <p class="mb-0 text-muted">@result.Notes</p>
                </div>
            }
        </div>

        <!-- Progress visualization -->
        <div class="card-footer">
            <div class="d-flex justify-content-between small text-muted mb-1">
                <span>Pending</span><span>Picked Up</span><span>In Transit</span><span>Out for Delivery</span><span>Delivered</span>
            </div>
            <div class="progress" style="height: 8px;">
                <div class="progress-bar @GetProgressBarColor(result.Status)" style="width: @GetProgressPercent(result.Status)%"></div>
            </div>
        </div>
    </div>
}

@code {
    private string trackingNumber = "";
    private string searchedNumber = "";
    private ShipmentDto? result;
    private bool searched;
    private bool isSearching;

    private async Task HandleKeyDown(KeyboardEventArgs e)
    {
        if (e.Key == "Enter") await Search();
    }

    private async Task Search()
    {
        if (string.IsNullOrWhiteSpace(trackingNumber)) return;
        isSearching = true;
        searchedNumber = trackingNumber.Trim();
        result = await ShipmentService.GetShipmentByTrackingNumberAsync(searchedNumber);
        searched = true;
        isSearching = false;
    }

    private static int GetProgressPercent(string status) => status switch
    {
        "Pending" => 10,
        "PickedUp" => 30,
        "InTransit" => 55,
        "OutForDelivery" => 80,
        "Delivered" => 100,
        _ => 0
    };

    private static string GetProgressBarColor(string status) => status switch
    {
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-primary"
    };

    private static string GetStatusBadge(string status) => status switch
    {
        "Pending" => "bg-secondary",
        "PickedUp" => "bg-info",
        "InTransit" => "bg-primary",
        "OutForDelivery" => "bg-warning text-dark",
        "Delivered" => "bg-success",
        "Cancelled" => "bg-danger",
        _ => "bg-secondary"
    };
}

