           @bind="filterText" @bind:event="oninput" />
</div>

@if (shipments is null)
{
    <p><em>Loading shipments...</em></p>
}
else if (!FilteredShipments.Any())
{
    <p>No shipments found.</p>
}
else
{
    <div class="table-responsive">
        <table class="table table-striped table-hover">
            <thead>
                <tr>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.TrackingNumber))" style="cursor:pointer">Tracking # ⇅</th>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.Destination))" style="cursor:pointer">Destination ⇅</th>
                    <th @onclick="() => SortBy(nameof(ShipmentDto.Status))" style="cursor:pointer">Status ⇅</th>
                    <th>Customer</th>
                    <th>Est. Delivery</th>
                    <th>Actions</th>
                </tr>
            </thead>
